// settings.ts
let currentUser: { id: string } | null = null;
export function setUser(u: { id: string }) {
  currentUser = u;
}
export function getUser() {
  return currentUser;
}
// other.ts
import { setUser, getUser } from "./settings";
setUser({ id: "alice" });
console.log(getUser());

const cache: Record<string, any> = {};
export function put(key: string, value: any) {
  cache[key] = value;
}
export function get(key: string) {
  return cache[key];
}
// tests call put/get without resetting the module state

// Version A
// shared module state
export const appState = { user: null as { id: string } | null };
export function setUser(u: { id: string }) { appState.user = u; }
export function getUser() { return appState.user; }

// Version B
// explicit state passed by caller
export type State = { user: { id: string } | null };
export function setUserExplicit(state: State, u: { id: string }) { state.user = u; }
export function getUserExplicit(state: State) { return state.user; }
